export const RULE_BY_ID = new Map<RuleId, RuleDefinition>(RULES.map((entry) => [entry.id, entry]));
export const CLASS_BY_ID = new Map(HERO_CLASSES.map((entry) => [entry.id, entry]));
export const ENEMY_BY_ID = new Map(ENEMIES.map((entry) => [entry.id, entry]));
export const EVENT_BY_ID = new Map(RUN_EVENTS.map((entry) => [entry.id, entry]));

export function getRule(id: RuleId): RuleDefinition {
  const value = RULE_BY_ID.get(id);
  if (!value) throw new Error(`Règle inconnue: ${id}`);
  return value;
}

export function getEnemy(id: string): EnemyDefinition {
  const value = ENEMY_BY_ID.get(id);
  if (!value) throw new Error(`Ennemi inconnu: ${id}`);
  return value;
}

export function getHeroClass(id: string): HeroClassDefinition {
  const value = CLASS_BY_ID.get(id as HeroClassDefinition["id"]);
  if (!value) throw new Error(`Classe inconnue: ${id}`);
  return value;
}

export function getBossEnemyId(bossId: BossId): string {
  return `boss-${bossId}`;
}
