import type { AbstractMesh, Scene, TransformNode } from "@babylonjs/core";
import { SceneLoader } from "@babylonjs/core";
import "@babylonjs/loaders/glTF";

interface ModelManifestEntry {
  enabled: boolean;
  url: string;
  rootNode?: string;
  scale?: number;
}

interface ModelManifest {
  version: number;
  models: Record<string, ModelManifestEntry>;
}

export class AssetRegistry {
  private manifest: ModelManifest = { version: 1, models: {} };

  public async initialize(): Promise<void> {
    try {
      const response = await fetch("./assets/models/manifest.json", { cache: "no-store" });
      if (response.ok) this.manifest = (await response.json()) as ModelManifest;
    } catch {
      this.manifest = { version: 1, models: {} };
    }
  }

  public hasModel(modelId: string): boolean {
    return Boolean(this.manifest.models[modelId]?.enabled);
  }

  public async instantiate(modelId: string, scene: Scene): Promise<TransformNode | AbstractMesh | undefined> {
    const entry = this.manifest.models[modelId];
    if (!entry?.enabled) return undefined;
    try {
      const result = await SceneLoader.ImportMeshAsync("", "", entry.url, scene);
      const root = entry.rootNode
        ? result.transformNodes.find((node) => node.name === entry.rootNode)
        : result.transformNodes[0] ?? result.meshes[0];
      if (!root) return undefined;
      root.scaling.setAll(entry.scale ?? 1);
      return root;
    } catch (error) {
      console.warn(`Modèle ${modelId} indisponible, utilisation du fallback procédural.`, error);
      return undefined;
    }
  }
}
