import type { Vec2i } from "./types";

export function distanceSquared(first: Vec2i, second: Vec2i): number {
  const dx = second.x - first.x;
  const dz = second.z - first.z;
  return dx * dx + dz * dz;
}

export function distance(first: Vec2i, second: Vec2i): number {
  return Math.sqrt(distanceSquared(first, second));
}

export function withinRadius(first: Vec2i, second: Vec2i, radius: number): boolean {
  return distanceSquared(first, second) <= radius * radius;
}

export function moveToward(origin: Vec2i, target: Vec2i, maxDistance: number): Vec2i {
  const dx = target.x - origin.x;
  const dz = target.z - origin.z;
  const magnitude = Math.sqrt(dx * dx + dz * dz);
  if (magnitude === 0 || magnitude <= maxDistance) return { ...target };
  const ratio = maxDistance / magnitude;
  return {
    x: Math.round(origin.x + dx * ratio),
    z: Math.round(origin.z + dz * ratio)
  };
}

export function moveAway(origin: Vec2i, threat: Vec2i, maxDistance: number, arenaRadius = 650): Vec2i {
  const dx = origin.x - threat.x;
  const dz = origin.z - threat.z;
  const magnitude = Math.sqrt(dx * dx + dz * dz) || 1;
  const next = {
    x: Math.round(origin.x + (dx / magnitude) * maxDistance),
    z: Math.round(origin.z + (dz / magnitude) * maxDistance)
  };
  const nextMagnitude = Math.sqrt(next.x * next.x + next.z * next.z);
  if (nextMagnitude <= arenaRadius) return next;
  const ratio = arenaRadius / nextMagnitude;
  return { x: Math.round(next.x * ratio), z: Math.round(next.z * ratio) };
}

export function clamp(value: number, minimum: number, maximum: number): number {
  return Math.max(minimum, Math.min(maximum, value));
}

export function percentage(value: number, maximum: number): number {
  return maximum <= 0 ? 0 : (value / maximum) * 100;
}
