import type { EventEnvelope } from "./types";

export function summarizeEvent(event: EventEnvelope): string {
  switch (event.type) {
    case "CombatStarted": return `Ouverture de ${String(event.payload.encounter ?? "la salle")}`;
    case "TelegraphStarted": return `${event.sourceId ?? "Un ennemi"} prépare une attaque`;
    case "AttackStarted": return `${event.sourceId ?? "?"} attaque ${event.targetId ?? "?"}`;
    case "ProjectileCreated": return `Projectile vers ${event.targetId ?? "la cible"}`;
    case "DamageDealt": return `${event.targetId ?? "?"} subit ${String(event.payload.applied ?? event.payload.amount ?? "?")} dégâts`;
    case "CriticalHit": return `Coup critique sur ${event.targetId ?? "la cible"}`;
    case "Dodged": return `${event.targetId ?? "La cible"} esquive`;
    case "StatusApplied": return `${statusLabel(String(event.payload.status))} ×${String(event.payload.stacks ?? 1)} sur ${event.targetId ?? "?"}`;
    case "StatusTick": return `${statusLabel(String(event.payload.status))} inflige ${String(event.payload.amount ?? "?")}`;
    case "StatusExpired": return `${statusLabel(String(event.payload.status))} s’achève`;
    case "ShieldGained": return `${event.targetId ?? "?"} gagne ${String(event.payload.amount ?? "?")} bouclier`;
    case "ShieldBroken": return `Bouclier de ${event.targetId ?? "?"} brisé`;
    case "EnemyKilled": return `${event.targetId ?? "Un ennemi"} est effacé`;
    case "AllyKilled": return `${event.targetId ?? "Un allié"} tombe`;
    case "ExplosionCreated": return `Explosion de rayon ${String(event.payload.radius ?? "?")}`;
    case "ShardsCreated": return `${String(event.payload.count ?? 0)} éclats libérés`;
    case "HealingReceived": return `${event.targetId ?? "?"} récupère ${String(event.payload.applied ?? event.payload.amount ?? "?")} PV`;
    case "GoldDropped": return `${String(event.payload.amount ?? 0)} or récupéré`;
    case "InkGained": return `${String(event.payload.amount ?? 0)} Encre gagnée`;
    case "RuleTriggered": return `Règle : ${String(event.payload.ruleName ?? event.causeRuleId ?? "?")}`;
    case "RewriteUsed": return String(event.payload.message ?? `Réécriture ${String(event.payload.kind ?? "")}`);
    case "BossMechanic": return bossMessage(event);
    case "ActorSummoned": return `${event.targetId ?? "Un serviteur"} rejoint le combat`;
    case "CombatEnded": return String(event.payload.result) === "victory" ? "La salle est vaincue" : "Le héros est tombé";
    default: return event.type;
  }
}

export function eventIcon(event: EventEnvelope): string {
  switch (event.type) {
    case "RuleTriggered": return "📜";
    case "StatusApplied": return statusIcon(String(event.payload.status));
    case "ExplosionCreated": return "💥";
    case "EnemyKilled": return "💀";
    case "HealingReceived": return "✚";
    case "RewriteUsed": return "✒️";
    case "BossMechanic": return "♛";
    case "CriticalHit": return "✦";
    case "Dodged": return "💨";
    default: return "·";
  }
}

function statusLabel(status: string): string {
  if (status === "burn") return "Brûlure";
  if (status === "poison") return "Poison";
  if (status === "freeze") return "Gel";
  if (status === "haste") return "Hâte";
  if (status === "weakness") return "Faiblesse";
  if (status === "vulnerability") return "Vulnérabilité";
  return status;
}

function statusIcon(status: string): string {
  if (status === "burn") return "🔥";
  if (status === "poison") return "☣️";
  if (status === "freeze") return "❄️";
  if (status === "haste") return "💨";
  return "◈";
}

function bossMessage(event: EventEnvelope): string {
  const kind = String(event.payload.kind ?? "");
  if (kind === "censure") return `L’Inquisiteur censure ${String(event.payload.ruleId ?? "une règle")}`;
  if (kind === "devour") return `Le Bibliophage dévore ${String(event.payload.ruleId ?? "une règle")}`;
  if (kind === "reverse") return "Le Roi Inversé retourne l’ordre du Codex";
  if (kind === "copy") return `Le Juge copie ${String(event.payload.ruleName ?? "votre loi")}`;
  if (kind === "corrupt") return `L’Auteur corrompt la règle ${Number(event.payload.index ?? 0) + 1}`;
  if (kind === "phase") return `Le boss entre en phase ${String(event.payload.phase ?? "?")}`;
  return "Le boss attaque le Codex";
}
