export class SeededRng {
  private state: number;

  public constructor(seed: number) {
    this.state = seed >>> 0 || 0x9e3779b9;
  }

  public nextUint(): number {
    let value = this.state;
    value ^= value << 13;
    value ^= value >>> 17;
    value ^= value << 5;
    this.state = value >>> 0;
    return this.state;
  }

  public nextFloat(): number {
    return this.nextUint() / 0x1_0000_0000;
  }

  public int(minInclusive: number, maxInclusive: number): number {
    const min = Math.ceil(minInclusive);
    const max = Math.floor(maxInclusive);
    if (max < min) throw new Error(`Intervalle invalide: ${min}..${max}`);
    return min + Math.floor(this.nextFloat() * (max - min + 1));
  }

  public chance(percent: number): boolean {
    return this.nextFloat() * 100 < Math.max(0, Math.min(100, percent));
  }

  public pick<T>(items: readonly T[]): T {
    if (items.length === 0) throw new Error("Impossible de choisir dans une liste vide");
    const value = items[this.int(0, items.length - 1)];
    if (value === undefined) throw new Error("Sélection aléatoire hors limites");
    return value;
  }

  public shuffle<T>(items: readonly T[]): T[] {
    const result = [...items];
    for (let index = result.length - 1; index > 0; index -= 1) {
      const other = this.int(0, index);
      [result[index], result[other]] = [result[other] as T, result[index] as T];
    }
    return result;
  }

  public weightedPick<T>(items: ReadonlyArray<{ value: T; weight: number }>): T {
    const total = items.reduce((sum, item) => sum + Math.max(0, item.weight), 0);
    if (total <= 0) throw new Error("Somme de poids invalide");
    let cursor = this.nextFloat() * total;
    for (const item of items) {
      cursor -= Math.max(0, item.weight);
      if (cursor <= 0) return item.value;
    }
    const fallback = items.at(-1)?.value;
    if (fallback === undefined) throw new Error("Liste pondérée vide");
    return fallback;
  }

  public fork(salt: number): SeededRng {
    return new SeededRng((this.state ^ Math.imul(salt, 0x45d9f3b)) >>> 0);
  }
}

export function hashString(value: string): number {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}
