import { useEffect, useRef, useState } from "react";
import { GameUi } from "../ui/GameUi";
import { useGameStore } from "../ui/gameStore";
import { GameRuntime } from "./GameRuntime";
import { GamepadController } from "./GamepadController";

export function App(): React.JSX.Element {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const setRuntime = useGameStore((state) => state.setRuntime);
  const setSnapshot = useGameStore((state) => state.setSnapshot);
  const [error, setError] = useState<string>();

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const runtime = new GameRuntime(canvas, setSnapshot);
    const gamepad = new GamepadController();
    setRuntime(runtime);
    gamepad.start();
    runtime.initialize().catch((reason: unknown) => setError(reason instanceof Error ? reason.message : String(reason)));
    return () => {
      gamepad.dispose();
      runtime.dispose();
      setRuntime(undefined);
    };
  }, [setRuntime, setSnapshot]);

  return (
    <main className="game-shell">
      <canvas ref={canvasRef} className="game-canvas" aria-label="Arène de Rules of the Abyss" />
      <GameUi />
      {error && (
        <div className="fatal-error" role="alert">
          <h1>Le Codex refuse de s’ouvrir</h1>
          <p>{error}</p>
        </div>
      )}
    </main>
  );
}
