import {
  Color3,
  Mesh,
  MeshBuilder,
  Scene,
  StandardMaterial,
  Vector3
} from "@babylonjs/core";

interface TransientMesh {
  mesh: Mesh;
  material: StandardMaterial;
  age: number;
  lifetime: number;
  velocity: Vector3;
  angularVelocity: Vector3;
  startScale: number;
  endScale: number;
  fade: boolean;
}

export class VfxSystem {
  private readonly transients: TransientMesh[] = [];
  private serial = 0;
  private intensity = 1;

  public constructor(private readonly scene: Scene) {}

  public setIntensity(value: number): void {
    this.intensity = Math.max(0.2, Math.min(1, value));
  }

  public burst(position: Vector3, color: Color3, count = 8, power = 2.2, lifetime = 0.5): void {
    const actualCount = Math.max(2, Math.round(count * this.intensity));
    for (let index = 0; index < actualCount; index += 1) {
      const size = 0.045 + ((index * 13) % 5) * 0.018;
      const mesh = MeshBuilder.CreatePolyhedron(this.name("burst"), { type: 1, size }, this.scene);
      mesh.position.copyFrom(position);
      const material = this.emissiveMaterial(mesh.name, color, 1);
      mesh.material = material;
      const angle = (Math.PI * 2 * index) / actualCount + ((index * 17) % 11) * 0.03;
      const vertical = 0.35 + ((index * 37) % 7) * 0.1;
      this.transients.push({
        mesh,
        material,
        age: 0,
        lifetime,
        velocity: new Vector3(Math.cos(angle) * power, vertical * power, Math.sin(angle) * power),
        angularVelocity: new Vector3(index * 0.4, index * 0.7, index * 0.3),
        startScale: 1,
        endScale: 0.08,
        fade: true
      });
    }
  }

  public ring(position: Vector3, color: Color3, radius = 1.5, lifetime = 0.55, thickness = 0.055): void {
    const mesh = MeshBuilder.CreateTorus(this.name("ring"), { diameter: Math.max(0.1, radius * 2), thickness, tessellation: 64 }, this.scene);
    mesh.position.copyFrom(position);
    mesh.position.y = 0.045;
    mesh.rotation.x = Math.PI / 2;
    mesh.scaling.setAll(0.08);
    const material = this.emissiveMaterial(mesh.name, color, 0.92);
    mesh.material = material;
    this.transients.push({ mesh, material, age: 0, lifetime, velocity: Vector3.Zero(), angularVelocity: Vector3.Zero(), startScale: 0.08, endScale: 1, fade: true });
  }

  public telegraph(position: Vector3, color: Color3, radius: number, lifetime: number): void {
    const mesh = MeshBuilder.CreateDisc(this.name("telegraph"), { radius, tessellation: 64 }, this.scene);
    mesh.position.copyFrom(position);
    mesh.position.y = 0.025;
    mesh.rotation.x = Math.PI / 2;
    const material = this.emissiveMaterial(mesh.name, color, 0.26);
    material.backFaceCulling = false;
    mesh.material = material;
    this.transients.push({ mesh, material, age: 0, lifetime, velocity: Vector3.Zero(), angularVelocity: new Vector3(0, 1.4, 0), startScale: 0.35, endScale: 1, fade: true });
  }

  public beam(from: Vector3, to: Vector3, color: Color3, width = 0.045, lifetime = 0.12): void {
    const direction = to.subtract(from);
    const length = direction.length();
    if (length <= 0.001) return;
    const midpoint = from.add(to).scale(0.5);
    const mesh = MeshBuilder.CreateCylinder(this.name("beam"), { height: length, diameter: width, tessellation: 8 }, this.scene);
    mesh.position.copyFrom(midpoint);
    mesh.lookAt(to);
    mesh.rotation.x += Math.PI / 2;
    const material = this.emissiveMaterial(mesh.name, color, 0.95);
    mesh.material = material;
    this.transients.push({ mesh, material, age: 0, lifetime, velocity: Vector3.Zero(), angularVelocity: Vector3.Zero(), startScale: 1, endScale: 0.25, fade: true });
  }

  public slash(position: Vector3, color: Color3, radius = 1.1): void {
    const mesh = MeshBuilder.CreateTorus(this.name("slash"), { diameter: radius * 2, thickness: 0.06, tessellation: 48 }, this.scene);
    mesh.position.copyFrom(position);
    mesh.position.y += 0.7;
    mesh.rotation.x = Math.PI / 2.8;
    mesh.rotation.z = -0.7;
    const material = this.emissiveMaterial(mesh.name, color, 1);
    mesh.material = material;
    this.transients.push({ mesh, material, age: 0, lifetime: 0.18, velocity: Vector3.Zero(), angularVelocity: new Vector3(0, 2.6, 0), startScale: 0.55, endScale: 1.25, fade: true });
  }

  public update(deltaSeconds: number): void {
    for (let index = this.transients.length - 1; index >= 0; index -= 1) {
      const item = this.transients[index];
      if (!item) continue;
      item.age += deltaSeconds;
      const progress = Math.min(1, item.age / item.lifetime);
      item.mesh.position.addInPlace(item.velocity.scale(deltaSeconds));
      item.velocity.y -= 4.2 * deltaSeconds;
      item.mesh.rotation.x += item.angularVelocity.x * deltaSeconds;
      item.mesh.rotation.y += item.angularVelocity.y * deltaSeconds;
      item.mesh.rotation.z += item.angularVelocity.z * deltaSeconds;
      const scale = item.startScale + (item.endScale - item.startScale) * easeOut(progress);
      item.mesh.scaling.setAll(scale);
      if (item.fade) item.material.alpha = Math.max(0, 1 - progress);
      if (progress >= 1) {
        item.mesh.dispose();
        item.material.dispose();
        this.transients.splice(index, 1);
      }
    }
  }

  public clear(): void {
    for (const item of this.transients) {
      item.mesh.dispose();
      item.material.dispose();
    }
    this.transients.length = 0;
  }

  public dispose(): void {
    this.clear();
  }

  private emissiveMaterial(name: string, color: Color3, alpha: number): StandardMaterial {
    const material = new StandardMaterial(`${name}-material`, this.scene);
    material.emissiveColor = color;
    material.diffuseColor = color.scale(0.12);
    material.alpha = alpha;
    material.disableLighting = true;
    return material;
  }

  private name(prefix: string): string {
    this.serial += 1;
    return `vfx-${prefix}-${this.serial}`;
  }
}

function easeOut(value: number): number {
  return 1 - (1 - value) * (1 - value);
}
