export function resolveDeviceRatioLimit(viewportWidth: number): number {
  if (viewportWidth <= 700) return 1;
  if (viewportWidth <= 1100) return 1.25;
  return 1.5;
}

export function resolveMinimumFrameInterval(
  reducedMotion: boolean,
  systemReducedMotion: boolean,
  staticRouteScene: boolean,
): number {
  if (!reducedMotion && !systemReducedMotion) return 0;
  return staticRouteScene ? Number.POSITIVE_INFINITY : 100;
}
